export function summarizeNotificationDeliveries(deliveries) {
    if (deliveries.every((item) => item.status === 'pending'))
        return 'pending';
    if (deliveries.some((item) => item.status === 'pending' ||
        item.status === 'preparing' ||
        item.status === 'submitting' ||
        item.status === 'retrying'))
        return 'processing';
    if (deliveries.some((item) => item.status === 'unknown'))
        return 'unknown';
    if (deliveries.every((item) => item.status === 'accepted'))
        return 'completed';
    if (deliveries.every((item) => item.status === 'failed'))
        return 'failed';
    return 'partial';
}

